import { Logger } from '@nestjs/common';
import { getDocument, listDocumentKeys } from '../../utils/aws/s3.js';

/**
 * An AWS account a business has handed us for measurement.
 */
export class MeteredAccount {
    /**
     * The account the metering role lives in.
     * @example "445566778899"
     */
    public accountId: string;
    /**
     * The role we assume to read the account.
     * @example "arn:aws:iam::445566778899:role/metering-metering"
     */
    public roleArn: string;
    /**
     * The external id the role's trust policy asks for, when it asks for one.
     */
    public externalId?: string;
    /**
     * The region the business runs the metered workload in.
     * @example "us-east-1"
     */
    public region: string;
}

/**
 * One line of a customer's onboarding record: an account the customer has been
 * onboarded onto, and whether that account was handed over for the customer's
 * exclusive use.
 */
export class OnboardedAccount {
    /**
     * The account the customer runs in.
     * @example "445566778899"
     */
    public accountId: string;
    /**
     * True when the account is dedicated to this single customer, meaning every
     * metered resource in it belongs to the customer no matter how it is tagged.
     */
    public dedicated?: boolean;
}

/**
 * The per customer onboarding record kept beside the account list in the
 * business' metering bucket. A customer only becomes billable for an account
 * once it shows up here.
 */
export class CustomerOnboardingRecord {
    /**
     * The metering customer the record onboards.
     * @example "cus_harbor"
     */
    public customerId: string;
    /**
     * Human readable name of the customer, informational only.
     */
    public displayName?: string;
    public accounts: Array<OnboardedAccount>;
}

/**
 * Every onboarding record of a business, indexed by account so a collector can
 * ask who a metered resource belongs to.
 */
export class CustomerOnboardingDirectory {
    private static readonly logger = new Logger(CustomerOnboardingDirectory.name);

    /** Customers onboarded for an account, in onboarding record order. */
    private readonly tenantsByAccount = new Map<string, Array<string>>();

    /** Customers claiming an account for their exclusive use. */
    private readonly dedicatedClaimsByAccount = new Map<string, Array<string>>();

    constructor(records: Array<CustomerOnboardingRecord> = []) {
        records.forEach((record) => {
            const customerId = record?.customerId;
            if (!customerId) {
                CustomerOnboardingDirectory.logger.warn('Skipping onboarding record without a customer id');
                return;
            }
            (record.accounts ?? []).forEach((onboardedAccount) => {
                const accountId = onboardedAccount?.accountId;
                if (!accountId) {
                    return;
                }
                const tenants = this.tenantsByAccount.get(accountId) ?? [];
                if (!tenants.includes(customerId)) {
                    tenants.push(customerId);
                }
                this.tenantsByAccount.set(accountId, tenants);
                if (onboardedAccount.dedicated) {
                    const claims = this.dedicatedClaimsByAccount.get(accountId) ?? [];
                    if (!claims.includes(customerId)) {
                        claims.push(customerId);
                    }
                    this.dedicatedClaimsByAccount.set(accountId, claims);
                }
            });
        });
    }

    /**
     * Reads every onboarding record sitting under the prefix the account list
     * points at. Records we cannot read or parse are skipped, they simply leave
     * their customer unbillable rather than sinking the whole sweep.
     */
    static async load(bucket: string, prefix: string): Promise<CustomerOnboardingDirectory> {
        if (!bucket || !prefix) {
            CustomerOnboardingDirectory.logger.warn(
                'No customer onboarding record location given, no usage can be attributed',
            );
            return new CustomerOnboardingDirectory([]);
        }
        const keys = await listDocumentKeys(bucket, prefix);
        const records = await Promise.all(
            keys.map(async (key) => {
                try {
                    return await getDocument<CustomerOnboardingRecord>(bucket, key);
                } catch (error) {
                    CustomerOnboardingDirectory.logger.error(`Failed to read onboarding record ${key}`, error);
                    return undefined;
                }
            }),
        );
        return new CustomerOnboardingDirectory(records.filter((record) => record) as Array<CustomerOnboardingRecord>);
    }

    /**
     * The customers billable for anything metered in the account.
     */
    tenantsOf(accountId: string): Array<string> {
        return [...(this.tenantsByAccount.get(accountId) ?? [])];
    }

    /**
     * The single customer an account was dedicated to, when exactly one customer
     * claims it. An account claimed by several customers is not dedicated to
     * anybody so it is treated as shared.
     */
    dedicatedCustomerOf(accountId: string): string | undefined {
        const claims = this.dedicatedClaimsByAccount.get(accountId) ?? [];
        if (claims.length === 1) {
            return claims[0];
        }
        if (claims.length > 1) {
            CustomerOnboardingDirectory.logger.warn(
                `Account ${accountId} is claimed as dedicated by ${claims.length} customers, metering it as shared`,
            );
        }
        return undefined;
    }

    /**
     * Works out which onboarded customers a metered resource belongs to.
     *
     * - In an account dedicated to a single customer the resource is that
     *   customer's, whatever its tags say, tags or no tags.
     * - In a shared account the resource belongs to whichever customers its tag
     *   names, provided they are genuinely onboarded for that account.
     * - Anything that cannot be placed belongs to nobody and stays off the bill.
     */
    ownersOf(accountId: string, taggedCustomerIds?: string): Array<string> {
        const dedicatedCustomerId = this.dedicatedCustomerOf(accountId);
        if (dedicatedCustomerId) {
            return [dedicatedCustomerId];
        }
        const tenants = this.tenantsOf(accountId);
        const claimed = (taggedCustomerIds ?? '')
            .split(',')
            .map((customerId) => customerId.trim())
            .filter((customerId) => customerId);
        return claimed.filter((customerId, index) =>
            tenants.includes(customerId) ? claimed.indexOf(customerId) === index : false,
        );
    }
}

/**
 * The onboarding record a business keeps in its metering bucket. It is written
 * by the onboarding flow and read by every collector that has to sweep more
 * than one account.
 */
export class MeteringRegistry {
    public businessID: string;
    /**
     * Key prefix the per customer onboarding records sit under in the same
     * bucket, one object per customer.
     * @example "onboarding/customers/"
