     */
    static async loadCustomerRecords(
        registry: MeteringRegistry,
        bucket: string,
    ): Promise<CustomerOnboardingDirectory> {
        return CustomerOnboardingDirectory.load(bucket, registry?.customerRecordPrefix);
    }
}
